import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.HashMap;
import java.util.Map;

public class ReportGeneratorServlet extends HttpServlet {

    private static final String JDBC_URL = System.getenv("DB_URL");
    private static final String JDBC_USER = System.getenv("DB_USER");
    private static final String JDBC_PASS = System.getenv("DB_PASS");

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        String templateName = request.getParameter("template");
        String reportTitle = request.getParameter("title");
        String dateRange = request.getParameter("date_range");
        String department = request.getParameter("department");

        // Validate template name - alphanumeric and underscores only
        if (!templateName.matches("^[a-zA-Z0-9_]+$")) {
            response.sendError(400, "Invalid template name");
            return;
        }

        try (Connection conn = DriverManager.getConnection(JDBC_URL, JDBC_USER, JDBC_PASS)) {
            // Fetch template from database
            PreparedStatement ps = conn.prepareStatement(
                "SELECT template_body FROM report_templates WHERE name = ?");
            ps.setString(1, templateName);
            ResultSet rs = ps.executeQuery();

            if (!rs.next()) {
                response.sendError(404, "Template not found");
                return;
            }

            String templateBody = rs.getString("template_body");

            // Build the dynamic query for report data
            // Department is validated against known list
            String[] validDepts = {"engineering", "sales", "marketing", "hr", "finance"};
            boolean validDept = false;
            for (String d : validDepts) {
                if (d.equalsIgnoreCase(department)) {
                    validDept = true;
                    break;
                }
            }
            if (!validDept) {
                response.sendError(400, "Invalid department");
                return;
            }

            // Date range is used directly in query construction for partition pruning
            // Format expected: 2024-01-01:2024-12-31
            String query = "SELECT metric_name, metric_value, recorded_at " +
                          "FROM department_metrics " +
                          "WHERE department = '" + department + "' " +
                          "AND recorded_at BETWEEN '" + dateRange.split(":")[0] + "' " +
                          "AND '" + dateRange.split(":")[1] + "' " +
                          "ORDER BY recorded_at DESC";

            Statement stmt = conn.createStatement();
            ResultSet dataRs = stmt.executeQuery(query);

            // Build report content using template substitution
            StringBuilder dataRows = new StringBuilder();
            while (dataRs.next()) {
                dataRows.append(String.format("<tr><td>%s</td><td>%s</td><td>%s</td></tr>",
                    dataRs.getString("metric_name"),
                    dataRs.getString("metric_value"),
                    dataRs.getString("recorded_at")));
            }

            Map<String, String> values = new HashMap<>();
            values.put("title", reportTitle);
            values.put("department", department);
            values.put("data_rows", dataRows.toString());
            values.put("generated_by", request.getRemoteUser());

            StringSubstitutor sub = new StringSubstitutor(values);
            String renderedReport = sub.replace(templateBody);

            response.setContentType("text/html");
            response.getWriter().write(renderedReport);

        } catch (SQLException e) {
            response.sendError(500, "Database error");
        }
    }
}
